for i=1,#cipher do local b=bx(cipher:byte(i),M[(i-1)%768+1]) sum=(sum+b*i)%4294967291 o[i]=string.char(b) end
local source=table.concat(o)
cipher=nil M=nil
if #source~=sourceLen or sum~=expected then return fail("integrity "..#source.."/"..sourceLen.." sum "..sum.."/"..expected) end
local fn,err=(loadstring or load)(source)
if not fn then return fail(tostring(err or "load failed")) end
local ok,rerr=pcall(fn)
if not ok then fail(tostring(rerr or "execution failed")) end